# Khan Academy Content Integration
import requests

KHAN_API_KEY = "b371671fd071f80a4477f8f3b2812b3d4fc687d7"
BASE_URL = "https://api.khanacademy.org/api/v1"

def get_khan_content(topic):
    """Get educational content from Khan Academy"""
    response = requests.get(
        f"{BASE_URL}/search/topics",
        params={
            "query": topic,
            "api_key": KHAN_API_KEY
        }
    )
    return response.json()

def get_exercises(topic_id):
    """Get exercises for a topic"""
    response = requests.get(
        f"{BASE_URL}/topic/{topic_id}/exercises",
        params={"api_key": KHAN_API_KEY}
    )
    return response.json()
